actions.script:
def qrNumber = invoice?.gstInvoiceNumber ?: invoice?.customInvoiceNumber
if (qrNumber) {
    def hints = new java.util.EnumMap(com.google.zxing.EncodeHintType)
    hints.put(com.google.zxing.EncodeHintType.MARGIN, 4)
    hints.put(com.google.zxing.EncodeHintType.ERROR_CORRECTION,
        com.google.zxing.qrcode.decoder.ErrorCorrectionLevel.M)
    invoiceQrMatrix = new com.google.zxing.qrcode.QRCodeWriter().encode(
        qrNumber.toString(), com.google.zxing.BarcodeFormat.QR_CODE, 0, 0, hints)
}

if (invoice != null) {
    def rmode = java.math.RoundingMode.HALF_UP
    def totCgst = BigDecimal.ZERO, totSgst = BigDecimal.ZERO, totIgst = BigDecimal.ZERO
    def enriched = []
    def detailsByLine = ec.entity.find('zenith.erp.tax.TaxLineDetail')
            .condition('referenceType', 'InvoiceItem').condition('referenceId', invoice.invoiceId)
            .orderBy('sequenceNum').list().groupBy { it.referenceSeqId }
    for (it0 in invoiceItems) {
        def m = new LinkedHashMap(it0)
        def tlds = detailsByLine[it0.invoiceItemSeqId]
        // The item's stored totalTaxAmount is authoritative: an EXPLICIT 0 means a tax-off line —
        // ignore any stale TaxLineDetail rows (seen when the tax toggle changed mid-sale). Only a
        // NULL item tax (older/manual rows) lets the breakdown rows speak for themselves.
        def storedGst = ((it0.cgstAmount ?: 0) + (it0.sgstAmount ?: 0) + (it0.igstAmount ?: 0)) as BigDecimal
        if (it0.totalTaxAmount != null && ((it0.totalTaxAmount as BigDecimal) == 0)) {
            tlds = null
            m.cgstAmount = 0G; m.sgstAmount = 0G; m.igstAmount = 0G
        }
        if (tlds) {
            // Breakdown rows replace the stored split; adding both doubles GST.
            m.cgstAmount = 0G; m.sgstAmount = 0G; m.igstAmount = 0G
            for (tl in tlds) {
                def nm = (tl.taxName ?: '').toUpperCase()
                def amt = (tl.taxAmount ?: 0) as BigDecimal
                def rt = (tl.taxRate ?: 0) as BigDecimal
                if (nm.contains('CGST')) { m.cgstAmount = ((m.cgstAmount ?: 0) as BigDecimal) + amt; m.cgstRate = rt }
                else if (nm.contains('SGST') || nm.contains('UTGST')) { m.sgstAmount = ((m.sgstAmount ?: 0) as BigDecimal) + amt; m.sgstRate = rt }
                else if (nm.contains('IGST')) { m.igstAmount = ((m.igstAmount ?: 0) as BigDecimal) + amt; m.igstRate = rt }
            }
        } else if (((it0.totalTaxAmount ?: 0) as BigDecimal) > 0 && storedGst != (it0.totalTaxAmount as BigDecimal)) {
            // Preserve a complete stored split (including legacy IGST). Infer
            // the historical local split only when no complete split exists.
            m.cgstAmount = 0G; m.sgstAmount = 0G; m.igstAmount = 0G
            // no stored breakdown (older rows): default to the intra-state 50/50 CGST/SGST split
            def itax = (it0.totalTaxAmount ?: 0) as BigDecimal
            def half = (itax / 2).setScale(2, rmode)
            m.cgstAmount = half; m.sgstAmount = itax - half
            def taxable = (it0.taxableAmount ?: 0) as BigDecimal
            if (taxable > 0) { m.cgstRate = (half * 100 / taxable).setScale(2, rmode); m.sgstRate = m.cgstRate }
        }
        if (m.cgstAmount) totCgst += m.cgstAmount as BigDecimal
        if (m.sgstAmount) totSgst += m.sgstAmount as BigDecimal
        if (m.igstAmount) totIgst += m.igstAmount as BigDecimal
        enriched.add(m)
    }
    invoiceItems = enriched
    // invoiceTotal is stored tax-INCLUSIVE (grand = taxable + tax), the system convention
    // (matches POS invoices + every receivables/aging/TCS/GSTR consumer). The printed Total
    // therefore adds only round-off; do NOT re-add tax (that would double-count).
    def inv = new LinkedHashMap(invoice)
    inv.totalCgst = totCgst; inv.totalSgst = totSgst; inv.totalIgst = totIgst
    inv.invoiceTotal = ((invoice.invoiceTotal ?: 0) as BigDecimal) + ((invoice.roundOffAmount ?: 0) as BigDecimal)
    // ZE-SETTINGS-001: the invoice's supplierGstin/buyerGstin snapshots are usually null -> the
    // print showed "GSTIN: Unregistered" even when the party has a GSTIN saved. Read the party's
    // saved GSTIN — the seller org's DEFAULT tax registration (what Company Setup edits) OR a
    // party's active IndiaGstin (the Contacts source, also used by some orgs) — when the invoice
    // didn't carry one. Display-only; no-op (stays Unregistered) if none saved — never fabricated —
    // and a genuine stored snapshot still wins.
    def _gstinOf = { pid ->
        def _out = null
        if (pid) {
            boolean _dz = ec.artifactExecution.disableAuthz()
            try {
                for (_r in ec.entity.find("zenith.erp.tax.TaxRegistration").condition("partyId", pid).orderBy("-isDefault").list())
                    { if (_r.registrationNumber) { _out = _r.registrationNumber; break } }
                if (!_out) for (_g in ec.entity.find("zenith.erp.india.IndiaGstin").condition("partyId", pid).condition("isActive", "Y").list())
                    { if (_g.gstin) { _out = _g.gstin; break } }
            } finally { if (!_dz) ec.artifactExecution.enableAuthz() }
        }
        _out
    }
    if (!inv.supplierGstin) { def _s = _gstinOf(invoice.fromPartyId); if (_s) inv.supplierGstin = _s }
    if (!inv.buyerGstin) { def _b = _gstinOf(invoice.toPartyId); if (_b) inv.buyerGstin = _b }
    // ZE-SALES-023 (SL-045): communicate the place-of-supply fallback. A B2C / unregistered buyer has
    // no GSTIN or state (legitimate); GST law then sets the place of supply to the SUPPLIER's state ->
    // intra-state (CGST+SGST), which the tax engine already applies. The print showed POS "-", hiding
    // the applied rule. Derive the effective POS (buyer's state if any, else the supplier's state) +
    // flag the fallback. Display-only; a real place-of-supply / buyer state still wins; stays "-" only
    // when no supplier state is known either. Never fabricated.
    def _stName2 = { c -> (c ? ec.entity.find("zenith.erp.india.IndiaState").condition("stateCode", c).one()?.stateName : null) }
    def _gstState2 = { g -> (g && g.toString().trim().length() >= 2 && (g.toString().trim().substring(0,2) ==~ /[0-9]{2}/)) ? g.toString().trim().substring(0,2) : null }
    def _psCode = (inv.placeOfSupplyStateCode ?: null) ?: _gstState2(inv.buyerGstin)
    def _supCode = (inv.supplierStateCode ?: null) ?: _gstState2(inv.supplierGstin)
    boolean _posFallback = false
    // Only default to the supplier's state for a NORMAL domestic sale. Export POS is the destination
    // (never the supplier's state); RCM has its own rules — leave those as-is rather than mislabel.
    boolean _normalSale = (inv.isReverseCharge != 'Y' && inv.isExport != 'Y')
    if (!_psCode && _supCode && (((totIgst ?: 0) as BigDecimal) == 0) && _normalSale) { _psCode = _supCode; _posFallback = true }
    def _psName = _stName2(_psCode)
    placeOfSupplyDisplay = _psCode ? (_psCode + (_psName ? ' - ' + _psName : '')) : '-'
    placeOfSupplyIsFallback = _posFallback
    invoice = inv
}
